<?phpif ( ! defined( 'ABSPATH' ) ) {	exit;}/** * Scripts Class * Handles Scripts and Styles enqueues functionality. * * @class  UWA_Whatsapp_Msg_Scripts * @package Ultimate WooCommerce Auction Pro - Whatsapp Message Addon * @author Nitesh Singh  * @since 1.0 * */class UWA_Whatsapp_Msg_Scripts {		private static $instance;	/**	 * Returns the *Singleton* instance of this class.	 *	 * @return Singleton The *Singleton* instance.	 *	 */    public static function get_instance() {        if ( null === self::$instance ) {            self::$instance = new self();        }        return self::$instance;    }    /**	 * addon actions	 *	 */	public function __construct() {				/* Add admin side scripts */		add_action( 'admin_enqueue_scripts', array( $this, 			'uwa_whatsapp_msg_register_admin_scripts') );	}	/**	 * Manage admin side scripts	 	 *		 */	public function uwa_whatsapp_msg_register_admin_scripts( $hook_sufix ) {		$uwa_whatsapp_data = array(			'test_error_message' => __('Please make sure you have entered a mobile phone number and test message.', 				'woo_ua'),				);		/* Register globally scripts */		/*wp_register_script( 'uwa-twilio-sms-admin', UW_AUCTION_PRO_ASSETS_URL . '/js/addons/uwa-whatsapp-msg-admin.js', array('jquery'), UW_AUCTION_PRO_VERSION );						wp_localize_script('uwa-twilio-sms-admin', 'UWA_TWILIO_SMS', array('ajaxurl' => admin_url('admin-ajax.php'), 'UWA_TWILIO_SMS_NONCE' => 			wp_create_nonce('UtAajax-nonce') ));		wp_localize_script('uwa-twilio-sms-admin', 'uwa_twilio_data', $uwa_twilio_data);		wp_enqueue_script( 'uwa-twilio-sms-admin' );*/		/* Register globally scripts */		wp_register_script('uwa-whatsapp-msg-admin', UW_AUCTION_PRO_ASSETS_URL . '/js/addons/uwa-whatsapp-msg-admin.js', array('jquery'), UW_AUCTION_PRO_VERSION);				wp_localize_script('uwa-whatsapp-msg-admin', 'UWA_WHATSAPP_MESSAGE', array('ajaxurl' => admin_url('admin-ajax.php'), 			'UWA_WHATSAPP_MESSAGE_NONCE' => wp_create_nonce('UtAajax-nonce') ));		wp_localize_script('uwa-whatsapp-msg-admin', 'uwa_whatsapp_data', $uwa_whatsapp_data);		wp_enqueue_script('uwa-whatsapp-msg-admin');	}	}UWA_Whatsapp_Msg_Scripts::get_instance();